const src = $json.data ?? $json;
const user = src.user ?? {};
const text = String(src.text ?? src.message ?? src.caption ?? '').trim();
const engagement = Number(src.likesCount ?? 0) + Number(src.commentsCount ?? 0) + Number(src.sharesCount ?? 0);
const postUrl = String(src.url ?? src.postUrl ?? src.link ?? '');
const postId = String(src.postId ?? src.id ?? postUrl ?? '');
const authorId = user.id ?? src.userId ?? '';
return {
  json: {
    post_id: postId,
    post_url: postUrl,
    text,
    author_name: String(user.name ?? src.userName ?? src.authorName ?? ''),
    author_url: String(src.userUrl ?? (authorId ? `https://facebook.com/${authorId}` : '')),
    published_at: String(src.time ?? src.timestamp ?? src.date ?? ''),
    group_name: String(src.groupTitle ?? src.groupName ?? ''),
    engagement_count: engagement,
    engagement_score: Math.min(100, Math.round(20 * Math.log10(engagement + 1))),
    source_platform: $('Business Config').first().json.socialPlatform
  }
};

const state = $getWorkflowStaticData('global');
state.seenPosts = state.seenPosts || {};
const now = Date.now();
const ttl = 30 * 24 * 60 * 60 * 1000;
for (const [key, timestamp] of Object.entries(state.seenPosts)) {
  if (now - Number(timestamp) > ttl) delete state.seenPosts[key];
}
const fresh = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.text || j.text.length < 15) continue;
  const key = String(j.post_id || j.post_url || `${j.author_url}|${j.published_at}|${j.text.slice(0, 160)}`);
  if (state.seenPosts[key]) continue;
  state.seenPosts[key] = now;
  fresh.push(item);
}
return fresh;

