const analysis = $json.output ?? $json;
const post = $items('Remove Seen Posts')[$itemIndex]?.json ?? {};
const config = $items('Business Config')[0]?.json ?? {};
const clamp = value => Math.max(0, Math.min(100, Number(value) || 0));
const buyingIntent = clamp(analysis.buying_intent);
const serviceFit = clamp(analysis.service_fit);
const urgency = clamp(analysis.urgency);
const reachability = clamp(analysis.reachability);
const engagementScore = clamp(post.engagement_score);
const leadScore = Math.round(0.40 * buyingIntent + 0.25 * serviceFit + 0.20 * urgency + 0.10 * reachability + 0.05 * engagementScore);
const hot = Number(config.hotLeadThreshold ?? 75);
const warm = Number(config.warmLeadThreshold ?? 50);
const leadTemperature = leadScore >= hot ? 'Hot' : leadScore >= warm ? 'Warm' : 'Insight';
return {
  json: {
    ...post,
    ...analysis,
    buying_intent: buyingIntent,
    service_fit: serviceFit,
    urgency,
    reachability,
    content_priority: clamp(analysis.content_priority),
    confidence: clamp(analysis.confidence),
    lead_score: leadScore,
    lead_temperature: leadTemperature,
    discovered_at: new Date().toISOString(),
    status: leadTemperature === 'Hot' ? 'New - needs human review' : leadTemperature === 'Warm' ? 'Nurture' : 'Insight only'
  }
};

